def para(doc, text):
    p=doc.add_paragraph(text)
    p.paragraph_format.space_after=Pt(7)
    return p

manifest=[]
for n,g in enumerate(games,1):
    doc=Document()
    sec=doc.sections[0]
    sec.page_height=Cm(29.7); sec.page_width=Cm(21)
    sec.top_margin=Cm(1.8); sec.bottom_margin=Cm(1.8)
    sec.left_margin=Cm(2); sec.right_margin=Cm(2)
    for name in ['Normal','Title','Subtitle','Heading 1','Heading 2']:
        s=doc.styles[name]; s.font.name='Calibri'; s.font.color.rgb=RGBColor(0,0,0)
    for border in list(doc.styles.element.iter(qn('w:pBdr'))):
        border.getparent().remove(border)
    doc.styles['Normal'].font.size=Pt(11)
    doc.styles['Normal'].paragraph_format.line_spacing=1.08
    doc.styles['Title'].font.size=Pt(27)
    doc.styles['Heading 1'].font.size=Pt(16)
    doc.styles['Heading 1'].paragraph_format.space_before=Pt(14)
    doc.styles['Heading 1'].paragraph_format.space_after=Pt(7)
    doc.core_properties.title=f'Промт для разработки игры {g["name"]}'
    doc.core_properties.author='Русский Royale'
    doc.add_heading(f'Промт для игры {g["name"]}',0)
    para(doc, f'Русский Royale · Модуль {g["id"]} · Контракт RR Game Module v1 · 29 октября 2026')
    para(doc,'Передайте этот Word-файл нейросети целиком либо скопируйте весь его текст. Нейросеть должна создать архив исходников по заданию ниже. Полученный ZIP передайте интегратору сайта; доступ к аккаунту Cloudflare и пароли для разработки не нужны.')
    doc.add_heading('Задание разработчику',1)
    para(doc,f'Создай полноценную многопользовательскую игру «{g["name"]}» для {g["count"]} игроков. Идентификатор gameId: {g["id"]}. Реализуй правила ниже, собственное анимированное оформление и поставку по общему контракту. Это одна из девяти игр существующего каталога, пока отмеченных «В разработке».')
    doc.add_heading('Правила и определение результата',1)
    for i,p in enumerate(g['rules'],1): para(doc,f'{i}. {p}')
    doc.add_heading('Художественное задание',1)
    para(doc,f'Концепция: «{g["concept"]}». Палитра: {g["palette"]}.')
    para(doc,g['art'])
    doc.add_heading('Материалы и управление содержимым',1)
    para(doc,g['content'])
    para(doc,'Авторские демоматериалы положи отдельно от production-контента. В поставке укажи происхождение и лицензию всех изображений, звуков и текстов. Новые коллекции не должны заменять существующие правила, уроки или задания.')
    for heading,paras in COMMON:
        doc.add_heading(heading,1)
        for p in paras:
            p=p.replace('<slug>',g['id']).replace('<название>',g['name'])
            lo,hi=g['count'].split('–')
            p=p.replace('"minPlayers":N,"maxPlayers":N',f'"minPlayers":{lo},"maxPlayers":{hi}')
            p=p.replace('rr_<slug с подчёркиваниями>_', 'rr_'+g['id'].replace('-','_')+'_')
            para(doc,p)
    doc.add_heading('Проверки именно этой игры',1)
    para(doc,g['tests'])
    para(doc,f'Финальный результат: russian-royale-{g["id"]}-v1.zip с завершённой игрой, оригинальными ассетами, редактором содержимого, тестами и инструкцией подключения. Сначала реализуй весь цикл, затем проверь его и только после этого сформируй архив.')
    foot=sec.footer.paragraphs[0]; foot.alignment=2
    r=foot.add_run(); fld=OxmlElement('w:fldSimple'); fld.set(qn('w:instr'),'PAGE'); r._r.addnext(fld)
    name=f'{n:02d}_{g["id"]}_Промт.docx'
    doc.save(OUT/name)
    manifest.append({'file':name,'gameId':g['id'],'name':g['name'],'paragraphs':len(doc.paragraphs)})
(ROOT/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
with zipfile.ZipFile(ROOT/'Русский_Royale_9_промтов_Word.zip','w',zipfile.ZIP_DEFLATED) as z:
    for p in sorted(OUT.glob('*.docx')): z.write(p,p.name)
print(json.dumps(manifest,ensure_ascii=False))
